attempts.candidate:
import { db } from "@/lib/db";

export async function GET(request: Request) {
  const { q } = request.nextUrl.searchParams;
  const broadcasts = await db.broadcast.findMany({
    where: {
      title: {
        contains: q,
        mode: "insensitive",
      },
    },
    orderBy: {
      title: "asc",
    },
    include: {
      transmitter: true,
    },
  });

  return {
    broadcasts: broadcasts,
    total: broadcasts.length,
  };
}

